const Flying = (Base) =>
  class extends Base {
    move() { return `${super.move()}, flies`; }
  };

class Animal {
  move() { return "walks"; }
}

class Bird extends Flying(Animal) {}
class Bat extends Flying(Animal) {}
const FlyingAnimal = Flying(Animal);

console.log(new Bird().move());
console.log(Object.getPrototypeOf(Bird) === Object.getPrototypeOf(Bat));
console.log(new Bat() instanceof FlyingAnimal);
console.log(Object.getPrototypeOf(Object.getPrototypeOf(Bird)) === Animal);
